complete_click_handler = r"""document.querySelectorAll('[data-academy-action="complete"]').forEach((button) => {
    button.addEventListener('click', () => {
        if (
            button?.dataset?.loading === 'true' ||
            button?.disabled
        ) {
            return;
        }

        const missionId = String(
            button.getAttribute('data-mission-id') || ''
        ).trim();

        const missionTitle = String(
            button.getAttribute('data-mission-title') || ''
        ).trim();

        if (!missionId) return;

        setDashboardButtonLoadingState(
            button,
            true,
            'Opening...'
        );

        academyOpenMissionJournalV1(
            missionId,
            missionTitle
        );

        window.setTimeout(() => {
            if (button.isConnected) {
                setDashboardButtonLoadingState(
                    button,
                    false
                );
            }
        }, 260);
    });
});
"""

